// ====================== Initialization and Finalization ======================

// Verifies that initializing a database with missing basic API function
// pointers returns kNotImplementedError.
TEST_F(DbManagerTest, InitMissingApiImplementation) {
    auto test_missing = [&](auto member_ptr) {
        Database bad_db = db_;
        bad_db.*member_ptr = nullptr;
        EXPECT_EQ(DbManagerInitDb(&bad_db, true, "test_game", 0,
                                  unique_path_.c_str(), nullptr, nullptr),
                  kNotImplementedError);
    };

    test_missing(&Database::Init);
    test_missing(&Database::FlushSolvingTier);
    test_missing(&Database::Finalize);
    test_missing(&Database::SetValue);
    test_missing(&Database::SetRemoteness);
    test_missing(&Database::GetValue);
    test_missing(&Database::GetRemoteness);
}

// Verifies that initializing a database with an empty formal name triggers a
// fatal exit.
TEST_F(DbManagerTest, InitEmptyFormalNameDeath) {
    db_.formal_name[0] = '\0';
    EXPECT_DEATH(
        {
            DbManagerInitDb(&db_, true, "test_game", 0, unique_path_.c_str(),
                            nullptr, nullptr);
        },
        "");
}

// Verifies that initializing a database with an unterminated formal name
// triggers a fatal exit.
TEST_F(DbManagerTest, InitUnterminatedFormalNameDeath) {
    std::memset(db_.formal_name, 'A', sizeof(db_.formal_name));
    EXPECT_DEATH(
        {
            DbManagerInitDb(&db_, true, "test_game", 0, unique_path_.c_str(),
                            nullptr, nullptr);
        },
        "");
}

// Verifies that initializing a database in read-only mode successfully sets up
// the database without creating directories.
TEST_F(DbManagerTest, InitReadOnlySuccess) {
    EXPECT_CALL(mock_db_instance_,
                Init(StrEq("test_game"), 0, _, nullptr, nullptr))
        .WillOnce(Return(0));
    EXPECT_EQ(DbManagerInitDb(&db_, true, "test_game", 0, unique_path_.c_str(),
                              nullptr, nullptr),
              0);
    EXPECT_EQ(db_manager_current_db, &db_);
}

// Verifies that initializing a database in read-write mode successfully creates
// the required directory structure.
TEST_F(DbManagerTest, InitReadWriteCreatesDirectory) {
    std::string expected_full_path = unique_path_ + "/test_game/0/mock_db/";
    EXPECT_CALL(mock_db_instance_,
                Init(StrEq("test_game"), 0, StrEq(expected_full_path), nullptr,
                     nullptr))
        .WillOnce(Return(0));
    EXPECT_EQ(DbManagerInitDb(&db_, false, "test_game", 0, unique_path_.c_str(),
                              nullptr, nullptr),
              0);
}

// Verifies that failing to create the data directory returns a file system
// error.
TEST_F(DbManagerTest, InitMkdirFails) {
    // Create a regular file at unique_path_ instead of a directory
    int result = std::system(("touch " + unique_path_).c_str());
    (void)result;

    // Attempting to init read-write will call MkdirRecursive on
    // unique_path_ + "/test_game/0/mock_db/".
    // Since unique_path_ is a regular file, creating a subdirectory will fail.
    EXPECT_EQ(DbManagerInitDb(&db_, false, "test_game", 0, unique_path_.c_str(),
                              nullptr, nullptr),
              kFileSystemError);
}

// Verifies that initializing a database with a NULL data path defaults to
// "data/".
TEST_F(DbManagerTest, InitDefaultDataPath) {
    std::string expected_full_path = "data/test_game/0/mock_db/";
    EXPECT_CALL(mock_db_instance_,
                Init(StrEq("test_game"), 0, StrEq(expected_full_path), nullptr,
                     nullptr))
        .WillOnce(Return(0));
    // Even read-only creates the path string but doesn't mkdir
    EXPECT_EQ(
        DbManagerInitDb(&db_, true, "test_game", 0, nullptr, nullptr, nullptr),
        0);
}

// Verifies that re-initializing the database manager when a database is already
// active correctly calls Finalize on the old database.
TEST_F(DbManagerTest, ReInitCallsFinalizeOnOldDb) {
    EXPECT_CALL(mock_db_instance_, Init(_, _, _, _, _))
        .WillRepeatedly(Return(0));
    EXPECT_EQ(DbManagerInitDb(&db_, true, "test_game", 0, unique_path_.c_str(),
                              nullptr, nullptr),
              0);

    // We expect Finalize to be called on re-init AND TearDown
    EXPECT_CALL(mock_db_instance_, Finalize()).Times(2);
    EXPECT_EQ(DbManagerInitDb(&db_, true, "test_game", 0, unique_path_.c_str(),
                              nullptr, nullptr),
              0);
}

// Verifies that calling DbManagerFinalizeDb correctly finalizes the active
// database and clears the global pointer.
TEST_F(DbManagerTest, FinalizeWhenActive) {
    EXPECT_CALL(mock_db_instance_, Init(_, _, _, _, _)).WillOnce(Return(0));
    EXPECT_EQ(DbManagerInitDb(&db_, true, "test_game", 0, unique_path_.c_str(),
                              nullptr, nullptr),
              0);

    EXPECT_CALL(mock_db_instance_, Finalize()).Times(1);
    DbManagerFinalizeDb();
    EXPECT_EQ(db_manager_current_db, nullptr);
}

// Verifies that calling DbManagerFinalizeDb when no database is active safely
// does nothing.
TEST_F(DbManagerTest, FinalizeWhenNotActive) {
    EXPECT_CALL(mock_db_instance_, Finalize()).Times(0);
    DbManagerFinalizeDb();  // should not crash
}

